for (let i = 0; i < 60; i++) console.log(`  scheduler.queue[${i}] = { name: "q${i}", workers: ${(i * 7) % 13 + 1}, retry: "${(i % 5) + 1}m", ttl: "${(i % 3) + 1}h" }`);
